insert into mail_templates (project_id, kind, name, subject, html) values
((select id from projects where name='The Locos'), 'prospection', 'Prospection The Locos', 'The Locos (ex-SKA-P) • {{structure}}', '<div><div>Bonjour {{contact}},</div><div><br></div><div><b>The Locos (ex-SKA-P)</b>&nbsp;est en tournée en 2027 avec 6 nouveaux titres.</div><div><br></div><div>On s’en parle pour la programmation de {{structure}} ?</div><br></div><div><div><div>Sur scène c’est la grosse fête, ça tourne partout et le public répond présent !!! Tournée des salles en novembre 2026 et début 2027&nbsp;<b>(Cabaret Sauvage, Paris, le 20/11).&nbsp;</b></div><div>Tournée des festivals 2027 avec 6 nouveaux&nbsp;titres. Et toujours <b>les plus grands classiques de SKA-P en live !&nbsp;</b></div><div><br></div></div><div><b style="color:#990000">LIVE &amp; INFOS :</b>&nbsp;<a href="https://www.lartboristerie.com/professionnel/the-locos-pro/">https://www.lartboristerie.com/professionnel/the-locos-pro/</a></div><div></div><br></div>Merci pour ton retour,<div><br></div><div>À vite,</div>'),
((select id from projects where name='FAV'), 'prospection', 'Prospection FAV', 'FAV (Electro Pop) • {{structure}} • Automne 2027', '<div><div><div><div><div>Bonjour {{contact}},</div><div><br></div><div><b>FAV</b> est en tournée avec son EP <b><i>« Dive »</i></b>.</div><div><br></div><div>Penses-tu que le projet pourrait trouver une place dans la prog de {{structure}} ?</div><div><br></div><div><div>Accompagné par La Belle Électrique (SMAC Grenoble), FAV défend son nouveau live (duo Guitare/synthés et batterie sur scène) mêlant électro, pop et guitares aux accents rock.&nbsp;</div><div>Il enchaîne les premières parties pour Broken Back, Aime Simone, Tim Dup, Papooz….</div><div><br></div><div><b>Nouvel album + tournée salle à l’automne 2027 !&nbsp;</b></div></div><div><br></div><div><b style="color:#990000">LIVE &amp; INFOS :</b>&nbsp;<a href="https://www.lartboristerie.com/professionnel/fav-pro/">https://www.lartboristerie.com/professionnel/fav-pro/</a></div><div><br></div><div>Merci pour ton retour,</div><div><br></div><div>À vite,</div>'),
((select id from projects where name='Th/s /s Sh/t'), 'prospection', 'Prospection Th/s /s Sh/t', 'Th/s /s Sh/t (Rock Electro) • {{structure}}', '<div><div><div>Bonjour {{contact}},</div><div><br></div><div><b>Th/s /s Sh/t</b> sort son nouvel album<b>&nbsp;<i>« ΛV »</i></b>&nbsp;le 30/10/2026&nbsp;(Label Upton Park).</div><div><br></div><div>Penses-tu que le groupe peut trouver sa place dans la programmation de {{structure}} ?</div><div><br></div><div><div><b>MaMA Festival • 15/10/2026 • Backstage By The Mill • Invitations disponibles</b></div><div><br></div></div><div><div><div>A l’image des signes de<i>&nbsp;« ΛV »</i>&nbsp;(lambda V) qui s’inversent et se reflètent, TH/S /S SH/T font cohabiter le rock et l’électro.</div><div>Trio en live (guitare, basse/synthé et batterie), dans la veine de Carpenter Brut, Justice et Prodigy, Th/s /s Sh/t convainc son public à chaque concert !</div><div><br></div></div><b style="color:#990000">LIVE &amp; INFOS :</b><b>&nbsp;</b><a href="https://www.lartboristerie.com/professionnel/this-is-shit-pro/">https://www.lartboristerie.com/professionnel/this-is-shit-pro/</a></div><div><br></div><div>Merci pour ton retour,</div><div><br></div><div>À très vite,</div>'),
((select id from projects where name='Natalia M. King'), 'prospection', 'Prospection Natalia M. King', 'Natalia M. King (Blues / Jazz) • {{structure}}', '<div><div><div><div>Bonjour {{contact}},</div><div><br></div><div><b>Natalia M. King</b>&nbsp;est en tournée avec son album&nbsp;<b><i>« Afroblues »</i></b>.</div><div><br></div><div>Le projet pourrait trouver sa place dans la programmation de {{structure}} ?</div><div><br></div><div><div><div><div><div><div><div>Figure de référence du Jazz, Natalia revient avec<i>&nbsp;son 8ème album «&nbsp;Afroblues&nbsp;»</i>, mélangeant rock blues, afrobeat et électro sur fond d’hommage au Botswana. En trio sur scène (guitare, batterie, synthés), elle voyage entre les États-Unis de son enfance, la France où elle vit aujourd’hui, et l’Afrique de ses racines. Avec sa voix forte, ses grooves qui montent le public en transe et une énergie qui fait autant danser qu’elle touche, Natalia, artiste engagée et rassembleuse (droits LGBTQ+, lutte contre le racisme et le fascisme), transforme chacun de ses concerts en un moment solaire et résolument vivant.</div><div><br></div><div><b>Set Jazz/Blues également disponible !&nbsp;</b></div></div></div><br></div></div></div></div><div><b style="color:#990000">LIVE &amp; INFOS :</b><b>&nbsp;</b><a href="https://www.lartboristerie.com/professionnel/natalia-m-king-pro/">https://www.lartboristerie.com/professionnel/natalia-m-king-pro/</a></div><div><br></div><div>Merci pour ton retour,</div><div><br></div><div>À vite,</div>'),
(null, 'relance', 'Relance (générique)', '', '<div>Bonjour {{contact}},</div><div><br></div><div>Je reviens vers toi au sujet de <b>{{artiste}}</b> pour la programmation de {{structure}}.</div><div><br></div><div>As-tu pu y jeter une oreille ? Je reste dispo pour en parler, par mail ou par téléphone.</div><div><br></div><div>Merci pour ton retour,</div><div><br></div><div>À vite,</div>');
insert into settings(key,value) values ('prospect_signature', to_jsonb('<br><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="text-align:left; color:#000000; font-family:''Helvetica Neue'', sans-serif; font-size:14px;"> <tbody><tr> <td style="text-align:left; padding:0;"> Antho<br> <strong>Anthony Combe</strong><br> Direction - Booking<br> <a href="tel:+33602256978">+33 (0)6 02 25 69 78</a> <span style="margin:0 2px;">|</span> <a href="mailto:anthony@lartboristerie.com">anthony@lartboristerie.com</a><br> <a href="https://www.lartboristerie.com/" target="_blank">lartboristerie.com</a> <span style="margin:0 2px;">|</span> <a href="https://www.instagram.com/lartboristerie/" target="_blank">Instagram</a><br> <span style="font-size:12px;">SARL L''ArtBoristerie Productions - 48Bis rue Pajol, 75018 Paris</span><br> <a href="https://www.lartboristerie.com/" target="_blank"> <img src="https://www.lartboristerie.com/wp-content/uploads/2026/02/LArtBoristerie_LogoCouleur-scaled.png" alt="L''ArtBoristerie Logo" width="170" style="display:block; border:0; width:170px; height:auto;" data-unique-identifier="undefined" data-width="170"> </a> </td> </tr> </tbody></table>'::text)) on conflict (key) do update set value=excluded.value;
